import PohInput, { InputTypes, IPohInputProps } from '../Input';

const clearV = '';

export interface IPohSelectItem<T> {
  value: T | null;
  label: any;
}

interface IPohSelectPropsBase<T = string> extends Omit<IPohInputProps, 'onChange' | 'value'> {
  allowEmpty?: boolean;
  options?: IPohSelectItem<T>[];
}

interface IPohSelectPropsNotEmpty<T = string> extends IPohSelectPropsBase<T> {
  onChange?: (selectedValue: T) => void;
  value?: T;
}

interface IPohSelectPropsCanEmpty<T = string> extends IPohSelectPropsBase<T> {
  allowEmpty: true;
  onChange?: (selectedValue: T | null) => void;
  value?: T | null;
}

function PohSelect<T = string>({
  allowEmpty = false,
  onChange,
  value,
  options,
  ...rest
}: IPohSelectPropsNotEmpty<T> | IPohSelectPropsCanEmpty<T>) {
  return (
    <PohInput
      type={InputTypes.select}
      onChange={(v) =>
        v === clearV && allowEmpty ? onChange?.(null as any) : onChange?.(v as unknown as T)
      }
      value={value as unknown as string}
      {...rest}
    >
      {allowEmpty && <option value={clearV} key={clearV}>{` - ${rest.placeholder} - `}</option>}
      {options?.map((op) => (
        <option value={op.value ?? op.label} key={op.label}>
          {op.label}
        </option>
      ))}
    </PohInput>
  );
}

export default PohSelect;
